function mount142(){const home=document.getElementById('game-home'),menu=document.getElementById('game-home-menu');if(!home||!menu?.children.length||home.dataset.design142)return;home.dataset.design142='true';document.getElementById('game-home-title').innerHTML='DOMINA<br><em>LA RED.</em>';home.querySelector('.game-kicker').textContent='METRO / LAB · CIUDAD DE MÉXICO';home.querySelector('.game-home-copy>p').textContent='Tu turno en el taller. Tu ruta en cabina. Explora, diagnostica y pon la ciudad en marcha.';
 const brand=document.createElement('div');brand.className='brand142';brand.innerHTML='M / LAB <span>EXPERIENCIA FERROVIARIA</span>';home.append(brand);const actions=document.createElement('div');actions.className='home142-actions';actions.innerHTML='<button data-home142-library>Biblioteca</button><button data-home142-settings>Ajustes</button>';actions.querySelector('[data-home142-library]').onclick=()=>document.getElementById('documents-open').click();actions.querySelector('[data-home142-settings]').onclick=()=>window.metroGameShell105?.openSettings();home.append(actions);const lines=document.createElement('div');lines.className='lines142';lines.innerHTML='DOS LÍNEAS. UNA CIUDAD. <b>1</b><b>8</b>';home.append(lines);
 const paths={explore:'M5 20V7l3-3h8l3 3v13M7 20l-2 3m12-3 2 3M8 8h8v6H8zM8 17h1m6 0h1',maintenance:'m5 19 9-9m1-6a5 5 0 0 0-6 6l-6 6a2 2 0 0 0 3 3l6-6a5 5 0 0 0 6-6l-3 3-3-3z',operator:'M4 20h16M6 20V9h12v11M8 9V5h8v4M9 14h6M9 17h2m3 0h1',automatic:'M3 6h18v12H3zM8 22h8M12 18v4m-6-9 4-3 4 5 4-3',substations:'M4 21V5h16v16zM7 8h4m3 0h3M7 11h4m3 0h3m-4 2-3 4h3l-2 4'};
 for(const b of menu.querySelectorAll('[data-game-mode]')){const icon=document.createElement('span');icon.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+paths[b.dataset.gameMode]+'"/></svg>';b.insertBefore(icon,b.children[1]);}
}
